// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    keepMyEther c;
    function setUp() public { c = new keepMyEther(); }
    function testFuzz_property(uint256 amount, uint8 seed) public {
        vm.assume(amount > 0);
        RevertingReceiver reverter = new RevertingReceiver();
        address payable recipient = seed % 2 == 0 ? payable(address(reverter)) : payable(address(0xdead));

        address caller = address(0x1000);
        vm.deal(caller, amount);
        vm.prank(caller);
        (bool ok,) = address(c).call{value: amount}("");
        require(ok, "deposit failed");

        uint256 balanceBefore = c.balances(caller);
        uint256 contractBalanceBefore = address(c).balance;

        vm.prank(caller);
        (bool success,) = address(c).call(abi.encodeWithSelector(c.withdraw.selector));
        uint256 balanceAfter = c.balances(caller);
        uint256 contractBalanceAfter = address(c).balance;

        bool invariantHolds = true;
        if (success) {
            invariantHolds = (balanceAfter == 0 && contractBalanceAfter == contractBalanceBefore - balanceBefore);
        } else {
            invariantHolds = (balanceAfter == balanceBefore && contractBalanceAfter == contractBalanceBefore);
        }
        assertTrue(invariantHolds);
    }
}

contract RevertingReceiver {
    receive() external payable {
        revert("revert in receive");
    }
}
